import clsx from 'clsx';
import React, { useEffect, useMemo } from 'react';
import { isElement } from 'react-is';

import { suggestion } from './Suggestion.sty.js';
import { SuggestionDetails } from './SuggestionDetails.js';
import { _useId } from '../../../core/hooks/useId.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { _isStringChildren } from '../../../core/utils/is-string-children.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Highlight } from '../../../typography/Highlight.js';
import { _useFilterFieldContext } from '../hooks/useFilterFieldContext.js';
import { FilterFieldActions } from '../state/filter-field-state-reducer.js';

/** @internal */
export type _FilterFieldSuggestionMode = 'replace' | 'insert';

export type FilterFieldSuggestionProps = WithChildren &
  StylingProps &
  DataTestId & {
    /**
     * The value used when applying the suggestion.
     * @defaultValue undefined
     */
    value?: string;
    /**
     * The characters to add to the suggestion when applying.
     * @defaultValue space
     */
    trailing?: string;
    /**
     * Application mode.
     * @internal
     * @defaultValue replace
     */
    mode?: _FilterFieldSuggestionMode;
  };

type FilterFieldSuggestionSlots = {
  label: React.ReactNode[];
  details: React.ReactNode;
};

export const Suggestion = (props: FilterFieldSuggestionProps) => {
  const {
    value,
    trailing = ' ',
    mode = 'replace',
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    children,
  }: FilterFieldSuggestionProps = props;
  const { applySuggestion, dispatch, term, focusedSuggestion } =
    _useFilterFieldContext();
  const uniqueId = _useId({ prefix: 'suggestion' });

  const slots = useMemo(() => {
    const slots: FilterFieldSuggestionSlots = {
      label: [],
      details: null,
    };

    function getSlots(
      children: React.ReactNode,
      slots: FilterFieldSuggestionSlots,
    ) {
      React.Children.forEach(children, (child) => {
        if (isElement(child)) {
          switch (child.type) {
            // To be able to easily specify children in a suggestions array, we also
            // allow fragments and recursively push children to the corresponding slots.
            // e.g.
            //  const suggestions = [{ value: 'value', children: (
            //    <>
            //      Display Value
            //      <FilterField.SuggestionDetails>Details</FilterField.SuggestionDetails>
            //    </>
            //  )}]
            //  {suggestions?.map((suggestion) => (
            //    <FilterField.Suggestion key={suggestion.value} {...suggestion} />
            //  ))}
            //
            case React.Fragment:
              return getSlots(child.props.children, slots);
            case SuggestionDetails:
              slots.details = child;
              break;
            default:
              slots.label.push(child);
          }
        } else {
          slots.label.push(child);
        }
      });
    }
    getSlots(children, slots);

    return slots;
  }, [children]);

  const childIsText = _isStringChildren(slots.label);
  const isFocused = uniqueId === focusedSuggestion ? true : undefined;

  if (value === undefined && !childIsText) {
    // eslint-disable-next-line no-console
    console.warn(
      'Suggestion value: There is no value provided for a suggestion and the children are not text-only. The applied result may be unexpected.',
    );
  }

  let suggestionText = '';
  if (value) {
    suggestionText = value;
  } else if (childIsText) {
    suggestionText = slots.label.join('');
  }

  useEffect(() => {
    dispatch({
      type: FilterFieldActions.ADDSUGGESTION,
      payload: {
        id: uniqueId,
        applySuggestion: () => {
          applySuggestion(`${suggestionText}${trailing}`, mode);
        },
      },
    });

    return () =>
      dispatch({
        type: FilterFieldActions.REMOVESUGGESTION,
        payload: { id: uniqueId },
      });
    // Only run on mount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Flex
      as="li"
      data-testid={dataTestId}
      id={uniqueId}
      data-strato-filter-field-suggestion-id={uniqueId}
      role="option"
      aria-selected={isFocused}
      className={clsx(
        suggestion,
        { 'virtual-focus': isFocused },
        consumerClassName,
      )}
      onClick={() => {
        applySuggestion(`${suggestionText}${trailing ?? ''}`, mode);
      }}
      justifyContent="space-between"
      style={consumerStyle}
    >
      {/* The highlight splits the text into a mark and a span, need to wrap it to keep it together in the flex container */}
      <span>
        <Highlight term={term ?? ''}>
          {slots.label.length > 0 ? slots.label : value}
        </Highlight>
      </span>
      <div>{slots.details}</div>
    </Flex>
  );
};

Suggestion.displayValue = 'FilterField.Suggestion';
